 private void filters(){notice.setText("Preparando filtrosâ€¦");final String selected=scope;work.execute(()->{Set<String> genres=new TreeSet<>(),countries=new TreeSet<>(),languages=new TreeSet<>(),safe=new HashSet<>();for(int i=0;i<kids.length();i++){JSONObject k=kids.optJSONObject(i);safe.add((k.optBoolean("series")?"s":"f")+":"+k.optInt("tmdb"));}try{JSONArray rows=selected.equals("live")?channels:catalog;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(selected.equals("live")){genres.add(r.optString("category"));continue;}if(selected.equals("kids")?!safe.contains(r.optString("kind")+":"+r.optInt("id")):!selected.equals(r.optString("kind")))continue;JSONArray g=r.optJSONArray("genres"),a=r.optJSONArray("audio");if(g!=null)for(int j=0;j<g.length();j++)genres.add(g.optString(j));for(String c:r.optString("country").split(","))if(!c.isEmpty())countries.add(c);if(a!=null)for(int j=0;j<a.length();j++)languages.add(a.optString(j));}}catch(Exception ignored){}ui.post(()->{if(!scope.equals(selected))return;notice.setText("");filterDialog(genres,countries,languages);});});}
