 private String get(String address,int max)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(18000);try{if(c.getResponseCode()!=200)throw new IOException();return read(c.getInputStream(),max);}finally{c.disconnect();}}
 private String read(InputStream stream,int max)throws Exception{try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException();out.write(b,0,n);}return out.toString("UTF-8");}}
 private void image(ImageView view,String address){view.setImageResource(tv.iptvibe.mobile.R.mipmap.ic_launcher);if(!address.startsWith("https://"))return;view.setTag(address);Bitmap old=bitmaps.get(address);if(old!=null){view.setImageBitmap(old);return;}images.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>3*1024*1024)throw new IOException();out.write(b,0,n);}byte[] bytes=out.toByteArray();Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap!=null){bitmaps.put(address,bitmap);ui.post(()->{if(address.equals(view.getTag()))view.setImageBitmap(bitmap);});}}finally{c.disconnect();}}catch(Exception ignored){}});}
